import sys

def solve():
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()

    total_g = s.count('G')
    if total_g == 0:
        print(0)
        return
    if total_g == n:
        print(n)
        return

    # Lengths of consecutive G to the left/right
    left = [0] * n
    right = [0] * n

    for i in range(n):
        if s[i] == 'G':
            left[i] = (left[i - 1] if i > 0 else 0) + 1

    for i in range(n - 1, -1, -1):
        if s[i] == 'G':
            right[i] = (right[i + 1] if i + 1 < n else 0) + 1

    ans = 0

    # Current maximum without any swap
    for i in range(n):
        if s[i] == 'G':
            ans = max(ans, left[i])

    # Try making each S into G by swapping with some G elsewhere
    for i in range(n):
        if s[i] == 'S':
            l = left[i - 1] if i > 0 else 0
            r = right[i + 1] if i + 1 < n else 0
            merged = l + r
            # If there exists at least one more G outside these merged ones,
            # we can swap this S with that G and get merged + 1
            if merged < total_g:
                ans = max(ans, merged + 1)
            else:
                ans = max(ans, merged)

    print(ans)

if __name__ == "__main__":
    solve()
